<template>
  <div class="valuation-page">
    <div class="valuation-crumb">财务管理 <i>/</i> 资金账户估值</div>
    <div class="valuation-heading">
      <div><h1>资金账户余额与估值</h1><p>当前估值仅反映参考价值，不改写收付款、转账或订单历史。</p></div>
      <div class="valuation-actions"><el-button class="manage-rate" @click="rateMaintenanceVisible = true">维护估值汇率</el-button><el-button type="success" class="green" @click="search">重新估值</el-button></div>
    </div>
    <section class="valuation-filter"><el-form inline size="small"><el-form-item label="估值日期"><el-date-picker v-model="query.valuation_date" type="date" value-format="yyyy-MM-dd" /></el-form-item><el-form-item label="账户币种"><el-select v-model="query.currency" clearable placeholder="全部"><el-option v-for="c in currencies" :key="c.currency_code" :label="`${c.currency_code} · ${c.currency_name}`" :value="c.currency_code" /></el-select></el-form-item><el-form-item label="账户关键字"><el-input v-model.trim="query.keyword" placeholder="请输入账户编号、账户名称/开户行" /></el-form-item><el-button class="green" type="success" @click="search">查询</el-button><el-button @click="reset">重置</el-button></el-form></section>
    <section class="metric-grid"><article><i class="el-icon-wallet wallet" /><small>资金账户数量</small><b>{{ total }} 个</b></article><article><i class="el-icon-money foreign" /><small>外币账户数</small><b>{{ foreignCount }} 个</b></article><article><i class="el-icon-data-analysis value" /><small>当前本位币估值合计</small><b>{{ money(summary.current_base_valuation_total) }} <em>CNY</em></b><p>仅统计已成功估值账户</p></article><article><i class="el-icon-trend-charts profit" /><small>未实现汇兑损益合计</small><b :class="Number(summary.unrealized_fx_gain_loss_total || 0) < 0 ? 'loss' : 'gain'">{{ signed(summary.unrealized_fx_gain_loss_total) }} <em>CNY</em></b><p>仅统计已成功估值账户</p></article></section>
    <p class="valuation-warning"><i class="el-icon-warning" /> 估值状态：<b :class="summary.valuation_complete ? 'ok' : 'warn'">{{ summary.valuation_complete ? '完整' : '不完整' }}</b> <span>{{ summary.valuation_complete ? '全部账户均成功估值' : `${summary.missing_rate_accounts || 0} 个账户缺少有效估值汇率` }}</span><em>缺失汇率不使用 0 或 1:1 代替</em></p>
    <section class="table-card"><el-table v-loading="loading" :data="rows" border size="small"><el-table-column label="账户编号" min-width="130"><template slot-scope="{row}">{{ row.account.account_no }}</template></el-table-column><el-table-column label="资金账户" min-width="140"><template slot-scope="{row}">{{ row.account.account_name }}</template></el-table-column><el-table-column label="账户币种" width="90"><template slot-scope="{row}">{{ row.account.currency }}</template></el-table-column><el-table-column label="原币余额" min-width="125" align="right"><template slot-scope="{row}">{{ money(row.original_balance) }} {{ row.account.currency }}</template></el-table-column><el-table-column label="历史账面价值(CNY)" min-width="145" align="right"><template slot-scope="{row}">{{ money(row.carrying_base_amount) }} CNY</template></el-table-column><el-table-column label="当前估值汇率" min-width="130" align="right"><template slot-scope="{row}">{{ rateText(row) }}</template></el-table-column><el-table-column label="当前本位币估值(CNY)" min-width="160" align="right"><template slot-scope="{row}">{{ row.current_base_valuation === null ? '—' : money(row.current_base_valuation) + ' CNY' }}</template></el-table-column><el-table-column label="未实现汇兑损益(CNY)" min-width="150" align="right"><template slot-scope="{row}"><span :class="Number(row.unrealized_fx_gain_loss) < 0 ? 'loss' : 'gain'">{{ row.unrealized_fx_gain_loss === null ? '—' : signed(row.unrealized_fx_gain_loss) + ' CNY' }}</span></template></el-table-column><el-table-column label="状态" min-width="140"><template slot-scope="{row}"><el-tag size="mini" :type="statusType(row)">{{ statusLabel(row) }}</el-tag><small v-if="row.block_reason" class="reason">{{ row.block_reason }}</small></template></el-table-column><el-table-column label="操作" width="92"><template slot-scope="{row}"><el-button v-if="row.valuation_status === 'missing_rate'" type="text" @click="rateMaintenanceVisible = true">维护汇率</el-button><el-button v-else type="text">查看</el-button></template></el-table-column></el-table><el-pagination background layout="total, sizes, prev, pager, next, jumper" :total="total" :current-page="page" :page-size="perPage" :page-sizes="[10,20,50,100]" @current-change="p => { page = p; load() }" @size-change="s => { perPage = s; page = 1; load() }" /></section>
    <finance-rate-maintenance-dialog :visible.sync="rateMaintenanceVisible" @changed="load" />
  </div>
</template>

<script>
import { listFinanceAccountValuations, listFinanceCurrencies } from '../../../api/erp/finance'
import FinanceRateMaintenanceDialog from './FinanceRateMaintenanceDialog.vue'

export default {
  components: { FinanceRateMaintenanceDialog },
  data: () => ({ loading: false, rows: [], currencies: [], page: 1, perPage: 20, total: 0, summary: {}, rateMaintenanceVisible: false, query: { valuation_date: new Date().toISOString().slice(0, 10), currency: '', status: '', keyword: '' } }),
  computed: { foreignCount () { return this.rows.filter(row => row.account?.currency && row.account.currency !== 'CNY').length } },
  created () { this.bootstrap(); if (this.$route.query.rate_maintenance === '1') this.rateMaintenanceVisible = true },
  methods: {
    async bootstrap () { try { const r = await listFinanceCurrencies({ per_page: 100, status: 'enabled' }); this.currencies = r.data.data || [] } catch (e) {} this.load() },
    async load () { this.loading = true; try { const r = await listFinanceAccountValuations({ ...this.query, page: this.page, per_page: this.perPage }); this.rows = r.data.data || []; this.total = Number(r.data.total || 0); this.summary = r.data.summary || {} } catch (e) { this.$message.error(e.userMessage || '账户估值加载失败') } finally { this.loading = false } },
    search () { this.page = 1; this.load() }, reset () { this.query = { valuation_date: new Date().toISOString().slice(0, 10), currency: '', status: '', keyword: '' }; this.search() },
    money (value) { return value === null || value === undefined ? '—' : Number(value).toLocaleString('zh-CN', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) }, signed (value) { const n = Number(value || 0); return `${n > 0 ? '+' : ''}${this.money(n)}` }, rate (value) { return Number(value).toFixed(4) }, rateText (row) { if (row.valuation_status === 'base_currency') return '—（本位币）'; if (row.valuation_status === 'zero_balance') return '—'; return row.valuation_rate === null ? '—' : `1 ${row.account.currency} = ${this.rate(row.valuation_rate)} CNY` }, statusLabel (row) { return ({ complete: '正常', zero_balance: '无需估值', base_currency: '本位币', missing_rate: '缺少估值汇率' })[row.valuation_status] || row.valuation_status }, statusType (row) { return row.valuation_status === 'missing_rate' ? 'danger' : row.valuation_status === 'zero_balance' ? 'info' : 'success' }
  }
}
</script>

<style scoped>
.valuation-page{padding:26px 24px 38px;min-height:calc(100vh - 64px);background:#fff;box-sizing:border-box}.valuation-crumb{font-size:14px;color:#647187;margin-bottom:22px}.valuation-crumb i{font-style:normal;color:#b5c0cf;margin:0 9px}.valuation-heading{display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:20px}.valuation-heading h1{margin:0 0 9px;font-size:26px;color:#121d33}.valuation-heading p{margin:0;color:#718099}.valuation-actions{display:flex;gap:10px}.manage-rate{border-color:#078948;color:#078948;min-width:128px}.green{background:#078948;border-color:#078948;min-width:116px}.valuation-filter,.metric-grid article,.table-card{background:#fff;border:1px solid #e2e8f0;border-radius:7px;box-shadow:0 3px 11px rgba(16,24,40,.035)}.valuation-filter{padding:20px 24px;margin-bottom:22px}.valuation-filter .el-form-item{margin:0 26px 0 0}.valuation-filter .el-form-item__label{display:block;float:none;text-align:left;padding:0 0 8px;line-height:20px;color:#36445e}.valuation-filter .el-input,.valuation-filter .el-select,.valuation-filter .el-date-editor{width:255px}.metric-grid{display:grid;grid-template-columns:1fr 1fr 1.2fr 1.2fr;gap:18px;margin-bottom:16px}.metric-grid article{position:relative;min-height:98px;padding:18px 22px}.metric-grid article>i{position:absolute;right:21px;top:22px;display:grid;place-items:center;width:48px;height:48px;border-radius:50%;font-size:26px}.wallet{color:#078948;background:#eaf8ef}.foreign{color:#2583e8;background:#eef6ff}.value{color:#0b9e68;background:#eaf8f0}.profit{color:#e98526;background:#fff4e9}.metric-grid small,.metric-grid p{display:block;color:#748198;font-size:13px;margin:0}.metric-grid b{display:block;font-size:25px;margin-top:11px;color:#121d33}.metric-grid b em{font-size:14px;font-style:normal}.metric-grid p{margin-top:6px}.valuation-warning{margin:0 0 16px;font-size:14px;color:#68768d}.valuation-warning i{color:#ef8c13;font-size:20px;vertical-align:middle;margin-right:8px}.valuation-warning em{font-size:13px;font-style:normal;margin-left:18px;color:#7c8798}.ok,.gain{color:#079455!important}.warn,.loss{color:#ed6b0b!important}.table-card{padding:14px;overflow:hidden}.table-card .el-pagination{margin-top:18px;text-align:right}.table-card :deep(.el-table th){background:#f7f9fc;color:#34425b;font-weight:600}.table-card small{display:block;color:#e77012;margin-top:5px;line-height:1.35}.reason{color:#d85c00;line-height:1.4}@media(max-width:1250px){.metric-grid{grid-template-columns:1fr 1fr}.valuation-filter .el-form-item{margin-bottom:12px}.table-card{overflow-x:auto}.table-card .el-table{min-width:1420px}}@media(max-width:620px){.valuation-page{padding:18px 14px}.valuation-heading{flex-direction:column;gap:12px}.valuation-actions{width:100%}.valuation-actions .el-button{flex:1}.valuation-filter .el-form-item,.valuation-filter .el-input,.valuation-filter .el-select,.valuation-filter .el-date-editor{width:100%;margin:0 0 10px}.metric-grid{grid-template-columns:1fr}.valuation-warning em{display:block;margin:8px 0 0}}
</style>
